test('RATES defined for EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const result = convert(1000, 'USD');
  assert.equal(result.ok, true);
  // 1000 EUR cents = 10 EUR, 10 EUR * 1.085 = 10.85 USD = 1085 USD cents
  assert.equal(result.value, 1085);
});

test('convert EUR to GBP', () => {
  const result = convert(1000, 'GBP');
  assert.equal(result.ok, true);
  // 1000 EUR cents = 10 EUR, 10 EUR * 0.8425 = 8.425 GBP = 842.5 GBP cents ≈ 843
  assert.equal(result.value, 843);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(1000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1000);
});

test('convert unknown currency returns error', () => {
  const result = convert(1000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with large amount', () => {
  const result = convert(123456, 'USD');
  assert.equal(result.ok, true);
  // 123456 EUR cents = 1234.56 EUR, 1234.56 * 1.085 = 1339.4076 USD = 133940.76 USD cents ≈ 133941
  assert.equal(result.value, 133941);
});

test('convert with small amount', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  // 1 EUR cent = 0.01 EUR, 0.01 EUR * 1.085 = 0.01085 USD = 1.085 USD cents ≈ 1
  assert.equal(result.value, 1);
});

test('convert negative amount', () => {
  const result = convert(-1000, 'USD');
  assert.equal(result.ok, true);
  // -1000 EUR cents * 1.085 = -1085 USD cents
  assert.equal(result.value, -1085);
});

test('formatMoney EUR', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
});

test('formatMoney USD', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
});

test('formatMoney GBP', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
});

test('formatMoney with thousands separators', () => {
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney unknown currency shows currency code', () => {
  assert.equal(formatMoney(123456, 'JPY'), 'JPY1,234.56');
});

test('convert and format flow', () => {
  const euros = 1000; // 10 EUR
  const usdResult = convert(euros, 'USD');
  assert.equal(usdResult.ok, true);
  const formatted = formatMoney(usdResult.value, 'USD');
  assert.equal(formatted, '$10.85');
});

